import{_ as s,o as a,c as e,a6 as p}from"./chunks/framework.B_q3ZJNF.js";const g=JSON.parse('{"title":"写回路径：少搬一次是一次","description":"","frontmatter":{"title":"写回路径：少搬一次是一次"},"headers":[],"relativePath":"nginx-internals-course/11-zero-copy-write-path.md","filePath":"nginx-internals-course/docs/11-zero-copy-write-path.md"}'),i={name:"nginx-internals-course/11-zero-copy-write-path.md"};function t(l,n,o,r,c,d){return a(),e("div",null,[...n[0]||(n[0]=[p(`<h1 id="写回路径-少搬一次是一次" tabindex="-1">写回路径：少搬一次是一次 <a class="header-anchor" href="#写回路径-少搬一次是一次" aria-label="Permalink to &quot;写回路径：少搬一次是一次&quot;">​</a></h1><p>大促当天，静态资源把带宽打满了。你登进机器想找瓶颈，<code>top</code> 里的画面很反常：nginx 的 CPU 已经 100%，但 active connections 才几百。按第 1 章的账，几百个连接对事件循环来说轻如鸿毛——CPU 忙什么去了？业务逻辑？静态文件没有业务逻辑。这几百个连接每个都在干同一件事：把磁盘上的文件发给网卡。<strong>数据只是从磁盘搬到网卡，谁也没加工它，CPU 却累到满格</strong>——问题出在「搬」的方式上。这一章算清这笔搬运账，算完你会得到全书最后两件省力的兵器：聚合写（把几堆数据合并成一次发送）与零拷贝（数据不进程序的家门，直达网卡）。然后我们站在终点，把十一章串成一张图。</p><h2 id="传统搬运-一次发送-四次拷贝" tabindex="-1">传统搬运：一次发送，四次拷贝 <a class="header-anchor" href="#传统搬运-一次发送-四次拷贝" aria-label="Permalink to &quot;传统搬运：一次发送，四次拷贝&quot;">​</a></h2><p>先看最朴素的写法：<code>read</code> 把文件读进来，<code>write</code> 把它发出去。看起来只有两步，但在操作系统内部，这段路要走四次搬运：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>磁盘 ──①──▶ 内核页缓存 ──②──▶ 用户程序内存 ──③──▶ socket 发送缓冲 ──④──▶ 网卡</span></span>
<span class="line"><span>      (DMA 搬)      (CPU 搬)                (CPU 搬)             (DMA 搬)</span></span></code></pre></div><p>①磁盘控制器直接把数据写进内核的页缓存（内核替所有程序统一管的那块文件缓存），这一步是 DMA 硬件搬的，CPU 只管发起；②<code>read</code> 返回时，内核把数据从页缓存复制一份到你的程序内存——CPU 搬；③<code>write</code> 时再从程序内存复制到 socket 的发送缓冲——CPU 搬；④网卡用 DMA 从发送缓冲拉走。</p><p>四次搬运里，②③两次是 CPU 亲自搬的，而且搬完就扔：你的程序读这份文件数据干什么？什么都不干，原样交出去。<strong>这两次搬运是纯粹的过路费</strong>。除了拷贝，还有过路费的另一半：<code>read</code> 和 <code>write</code> 各要跨越两次用户态与内核态的边界（调用进入内核、返回回到用户），一次发送四次<strong>上下文切换</strong>（和第 1 章进程切换同一个词：换身份、刷现场，纯付费不产出）。</p><p>跟着算总账：10 GB 的静态文件走传统路径，CPU 亲手搬运 20 GB（进出各一遍），上下文切换几十万次。大促那天你的 CPU，就是累死在这 20 GB 的过路费上——连接数不多，搬运量是天文数字。</p><h2 id="第一件兵器-聚合写-writev" tabindex="-1">第一件兵器：聚合写 writev <a class="header-anchor" href="#第一件兵器-聚合写-writev" aria-label="Permalink to &quot;第一件兵器：聚合写 writev&quot;">​</a></h2><p>第 8 章你可能已经隐约见过它的问题意识。发一个响应，手里通常是两块数据：头部一块、体一块。朴素写法发两次 <code>write</code>，两次系统调用、两次切换。<strong>聚合写</strong>（writev）——把几堆东西抱一次送出去：把「头部」和「体」两块内存的地址交给一次调用，内核一次搬完。两趟并一趟，系统调用减半。nginx 发响应头和响应体就是一次聚合写；tinysrv 的代理回写把头部和体拼成一个字符串再写，是同一件事的简化版。数据块越多、块越小，聚合的收益越大——精髓是：系统调用的次数取决于你跑几趟，不取决于数据有多大。</p><h2 id="第二件兵器-sendfile——货不进家门的直达通道" tabindex="-1">第二件兵器：sendfile——货不进家门的直达通道 <a class="header-anchor" href="#第二件兵器-sendfile——货不进家门的直达通道" aria-label="Permalink to &quot;第二件兵器：sendfile——货不进家门的直达通道&quot;">​</a></h2><p>writev 省的是趟数，sendfile 省的是整条路。<strong>零拷贝</strong>（zero copy）指的是：数据从头到尾不进你程序的家门——不搬到用户程序内存，自然也就没有「从程序内存搬出去」这一步。锚点：快递中转。传统路径是包裹先送到你家、你签收后再原封不动寄出去；零拷贝是包裹直接在中转站换车，你的地址从头到尾没上过面单。</p><p>Linux 给这条路修的官方通道叫 <strong>sendfile</strong>（一个系统调用：这个文件、这段范围、发到那个 socket）。内核在页缓存和网卡之间自己完成交接——CPU 拷贝次数从 2 次降到 0 次。配合现代网卡的分散收集 DMA，数据甚至不需要连续搬运：内核只把「数据在哪、多长」的描述符交给网卡，网卡自己来页缓存拉。上下文切换从 4 次降到 2 次（只有一次调用）。你大概猜到了 nginx 配置里那行 <code>sendfile on;</code> 是什么——它就是这条通道的开关，静态文件服务的标配。</p><p>第 5 章的内存池在这里有个漂亮的呼应：零拷贝的哲学和内存池是同一句话的两种说法——<strong>能不动的数据就不动，能不还的账就不记</strong>。内存池说：请求的内存整仓清退，别逐件归还；零拷贝说：路过的数据别领进门，别搬两趟冤枉路。</p><p>诚实边界也要说：sendfile 只适用于「文件原样发出」的场合。一旦数据要改（加响应头之外的加工、压缩、TLS 加密——gzip 之后数据必须重新生成），内核没法替你改文件，零拷贝链条就断了，回到普通路径。所以真实 nginx 的世界里 sendfile 与缓冲、压缩各行其道，互不取代。</p><h2 id="全书一张图-一个请求的完整旅程" tabindex="-1">全书一张图：一个请求的完整旅程 <a class="header-anchor" href="#全书一张图-一个请求的完整旅程" aria-label="Permalink to &quot;全书一张图：一个请求的完整旅程&quot;">​</a></h2><p>十一章走到这里，把所有零件装回一台 tinysrv（也就是一台 nginx 的骨架），看一个请求从生到死：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端</span></span>
<span class="line"><span>  │ TCP 三次握手（第 4 章算过它的账）</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>总机 accept（master 建的监听 socket，内核恰好交给一个 worker —— 第 7 章）</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>① 连接注册表入账：id / remote / lastActiveAt（第 2 章 —— 空闲收割的账本）</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>② HTTP 状态机：字节流 → 请求头，半包粘包免疫（第 3 章 —— pending 与三个格子）</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>③ keep-alive：这条连接接着说下一句，空闲 75 秒才挂（第 4 章 —— TIME_WAIT 的账）</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>④ 漏桶：按 IP 一人一桶，溢出即 503（第 10 章 —— 慢慢失败不如立刻失败）</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>⑤ 配置继承：这个房间的有效规则 = 沿花括号由外向内覆盖（第 6 章）</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>⑥ 出口分流 ── handler 直答 ──────────────┐</span></span>
<span class="line"><span>  │        └─ 反向代理（第 8 章：缓冲、X-Forwarded-For、502）</span></span>
<span class="line"><span>  │              └─ 负载均衡（第 9 章：轮询、摘除、试探回归）</span></span>
<span class="line"><span>  ▼                                      ▼</span></span>
<span class="line"><span>⑦ 写回：writev 聚合一次送 / sendfile 零拷贝直达（本章 —— 少搬一次是一次）</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>⑧ 请求内存池整仓清退（第 5 章 —— 防泄漏的结构性答案）</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>下一位客人（③ 的循环），或优雅关闭送客（第 7 章 QUIT 的语义）</span></span></code></pre></div><p>每一站你现在都能说出三件事。它挡住了哪类事故——第 1 章的 C10K、第 4 章的端口耗尽、第 5 章的内存泄漏、第 8 章的慢客户端、第 9 章的单点 502、第 10 章的雪崩。它的关键机制是什么——账本、状态机、失败账、懒结算。它省的是哪笔钱——连接挂着不费钱、少一次系统调用、少两次搬运、整仓清退。<strong>nginx 快而稳的全部秘密，就是这十一笔小账的叠加</strong>——没有魔法，只有每一层都被算清楚过的钱。</p><h2 id="读完本章-你该能回答" tabindex="-1">读完本章，你该能回答 <a class="header-anchor" href="#读完本章-你该能回答" aria-label="Permalink to &quot;读完本章，你该能回答&quot;">​</a></h2><ul><li>传统路径的「四次拷贝」哪两次是 CPU 搬的？为什么说它们是过路费？</li><li>writev 省什么、sendfile 省什么？两者的省法为什么不在一个层面上？</li><li>零拷贝和内存池的哲学为什么说是同一句话？sendfile 在什么场合会让位？</li><li>合上书，你能不看图复述一个请求经过的每一站和它背后的那笔账吗？</li></ul><p>课程正文到此完结。附录里还有三份常备资料：全书术语表、信号速查表、你配过的指令与本书机制的对照表——以及一份练习路线：清空 <code>src/</code>，让 52 个测试从红到绿再绿一遍。那时你拥有的就不只是「读懂」，而是「写得出」。</p>`,22)])])}const u=s(i,[["render",t]]);export{g as __pageData,u as default};
